def fault_hours(samples, max_gap_s):
    # Validate max_gap_s
    if not isinstance(max_gap_s, (int, float)) or isinstance(max_gap_s, bool):
        raise ValueError("max_gap_s must be a finite int/float, not bool")
    if max_gap_s <= 0 or max_gap_s != max_gap_s or abs(max_gap_s) == float('inf'):
        raise ValueError("max_gap_s must be a finite positive number")

    # Validate samples is a list
    if not isinstance(samples, list):
        raise ValueError("samples must be a list")

    # Validate each row and collect valid rows
    valid_rows = []
    seen_epochs = {}

    for i, row in enumerate(samples):
        # Row must be list/tuple of length 3
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            raise ValueError(f"Row {i} must be a list/tuple of length 3")

        epoch, fault, active = row

        # Validate epoch: must be finite numeric, not bool
        if isinstance(epoch, bool):
            raise ValueError(f"Epoch at index {i} must not be bool")
        if not isinstance(epoch, (int, float)):
            raise ValueError(f"Epoch at index {i} must be int/float")
        if epoch != epoch or abs(epoch) == float('inf'):
            raise ValueError(f"Epoch at index {i} must be finite")

        # Validate fault: must be actual bool or None
        if fault is not None and not isinstance(fault, bool):
            raise ValueError(f"Fault at index {i} must be bool or None")
        if isinstance(fault, bool) and fault not in (True, False):
            raise ValueError(f"Fault at index {i} must be bool or None")

        # Validate active: must be actual bool or None
        if active is not None and not isinstance(active, bool):
            raise ValueError(f"Active at index {i} must be bool or None")
        if isinstance(active, bool) and active not in (True, False):
            raise ValueError(f"Active at index {i} must be bool or None")

        # Handle duplicates: last row wins
        seen_epochs[epoch] = (epoch, fault, active)

    # Get unique rows sorted by epoch ascending
    unique_rows = sorted(seen_epochs.values(), key=lambda x: x[0])

    # Handle edge cases
    if len(unique_rows) <= 1:
        return (0.0, 0.0)

    fault_seconds = 0.0
    covered_seconds = 0.0

    for i in range(len(unique_rows) - 1):
        epoch, fault, active = unique_rows[i]
        next_epoch = unique_rows[i + 1][0]

        # Determine interval duration (capped at max_gap_s)
        interval = min(next_epoch - epoch, max_gap_s)

        # Skip if interval is non-positive (shouldn't happen due to sorting, but be safe)
        if interval <= 0:
            continue

        # Only contribute if active is True and fault is a bool
        if active is True and fault is not None:
            covered_seconds += interval
            if fault is True:
                fault_seconds += interval

    return (fault_seconds / 3600.0, covered_seconds / 3600.0)

