def motor_gate(kind, proofs, required=True):
    if not isinstance(required, bool):
        raise ValueError("required must be a bool")

    if required is False:
        return "ACTIVE"

    if kind not in ("ahu", "pump"):
        raise ValueError("kind must be 'ahu' or 'pump'")

    if not isinstance(proofs, dict):
        raise ValueError("proofs must be a dict")

    if kind == "ahu":
        selected = proofs.get("supply_fan", [])
    else:  # kind == "pump"
        selected = proofs.get("pumps", [])

    # Validate selected is a list or tuple
    if not isinstance(selected, (list, tuple)):
        raise ValueError("selected proof must be a list or tuple")

    # Check each item in selected
    for item in selected:
        if not isinstance(item, (bool, type(None))):
            raise ValueError("proof item must be bool or None")
        if item is True:
            return "ACTIVE"

    # If we get here, no True values found
    if len(selected) == 0:
        return "UNKNOWN"

    # Check if all are False (non-empty and no True/None)
    if all(item is False for item in selected):
        return "INACTIVE"

    # Otherwise, there must be at least one None and no True
    return "UNKNOWN"

